const unreadByKind = `-- name: UnreadByKind :many
SELECT c.kind::text AS kind, count(*)::int AS threads
FROM conversation_members me
JOIN conversations c ON c.id = me.conversation_id
WHERE me.user_id = $1 AND me.hidden_at IS NULL
  AND EXISTS (
    SELECT 1 FROM messages m
    WHERE m.conversation_id = c.id AND m.deleted_at IS NULL
      AND m.sender_id IS DISTINCT FROM $1::uuid
      AND (me.last_read_message_id IS NULL OR m.id > me.last_read_message_id)
  )
GROUP BY c.kind
`

type UnreadByKindRow struct {
	Kind    string `json:"kind"`
	Threads int32  `json:"threads"`
}

// The number on each tab of the inbox (MS-01).
func (q *Queries) UnreadByKind(ctx context.Context, userID uuid.UUID) ([]UnreadByKindRow, error) {
	rows, err := q.db.Query(ctx, unreadByKind, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []UnreadByKindRow{}
	for rows.Next() {
		var i UnreadByKindRow
		if err := rows.Scan(&i.Kind, &i.Threads); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const unreadConversations = `-- name: UnreadConversations :one
SELECT count(*)::int FROM conversation_members me
WHERE me.user_id = $1 AND me.hidden_at IS NULL
  AND EXISTS (
    SELECT 1 FROM messages m
    WHERE m.conversation_id = me.conversation_id AND m.deleted_at IS NULL
      AND m.sender_id IS DISTINCT FROM $1::uuid
      AND (me.last_read_message_id IS NULL OR m.id > me.last_read_message_id)
  )
`

func (q *Queries) UnreadConversations(ctx context.Context, userID uuid.UUID) (int32, error) {
	row := q.db.QueryRow(ctx, unreadConversations, userID)
	var column_1 int32
	err := row.Scan(&column_1)
	return column_1, err
}
